INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5273202, 768216, 84779, '<td valign="top">very creative,I always wanted to know how those things were put together</td>', 'very creative,I always wanted to know how those things were put together', '2009-02-25 00:06:43.000000', NULL, 1),
(5273229, 768253, 84779, '<td valign="top">its a lemon!!!roflmao</td>', 'its a lemon!!!roflmao', '2009-02-25 00:10:59.000000', NULL, 1),
(5273312, 768120, 47294, '<td valign="top">I love this photograph, absolutely beautiful and a very good take on the challenge.  Best of luck 10.</td>', 'I love this photograph, absolutely beautiful and a very good take on the challenge.  Best of luck 10.', '2009-02-25 00:25:31.000000', NULL, 1),
(5273313, 768110, 96751, '<td valign="top">nice textures and tones.</td>', 'nice textures and tones.', '2009-02-25 00:25:52.000000', NULL, 1),
(5273321, 766877, 96751, '<td valign="top">Clever idea.  The execution is a bit weak though.  I think the puzzle piece, though in focus, is also tonally too similar and the "hands" to tiny to make an impact - especially against the larger and out of focus main bodies.  Points for idea though.</td>', 'Clever idea.  The execution is a bit weak though.  I think the puzzle piece, though in focus, is also tonally too similar and the "hands" to tiny to make an impact - especially against the larger and out of focus main bodies.  Points for idea though.', '2009-02-25 00:27:19.000000', NULL, 1),
(5273327, 767993, 96751, '<td valign="top">Wonderful!  I love the shininess, the spikes, the tones, the really great metallic finish.  I want one.</td>', 'Wonderful!  I love the shininess, the spikes, the tones, the really great metallic finish.  I want one.', '2009-02-25 00:28:21.000000', NULL, 1),
(5273329, 767903, 96751, '<td valign="top">Interesting.  The shadow makes her look like a Picasso.</td>', 'Interesting.  The shadow makes her look like a Picasso.', '2009-02-25 00:28:56.000000', NULL, 1),
(5273334, 767006, 96751, '<td valign="top">Not quite a "puzzled" shot but definitely adorable.  The calf looks like he''s dozing off :-)  The sepia tones make this shot more interesting.</td>', 'Not quite a "puzzled" shot but definitely adorable.  The calf looks like he''s dozing off :-)  The sepia tones make this shot more interesting.', '2009-02-25 00:30:12.000000', NULL, 1),
(5273337, 767890, 96751, '<td valign="top">Nice!  Love the reflected/refracted images.  The composition is a bit cluttered though.</td>', 'Nice!  Love the reflected/refracted images.  The composition is a bit cluttered though.', '2009-02-25 00:30:48.000000', NULL, 1),
(5273343, 768107, 96751, '<td valign="top">Wonderful idea but there should have been more lighting on the ball, or made it "pop" more, maybe with a different color.  Even knowing it''s there, I don''t really see it because of the strong lines and the lighting of the maze.</td>', 'Wonderful idea but there should have been more lighting on the ball, or made it "pop" more, maybe with a different color.  Even knowing it''s there, I don''t really see it because of the strong lines and the lighting of the maze.', '2009-02-25 00:32:28.000000', NULL, 1),
(5273348, 767498, 96751, '<td valign="top">Wonderful!  Incredible detail and colors, just love how nature creates its own custom pieces.</td>', 'Wonderful!  Incredible detail and colors, just love how nature creates its own custom pieces.', '2009-02-25 00:33:13.000000', NULL, 1),
(5273354, 767951, 96751, '<td valign="top">Clever.  Thought the lighting is slightly graduated, it could have been even more so to make this a more interesting shot.</td>', 'Clever.  Thought the lighting is slightly graduated, it could have been even more so to make this a more interesting shot.', '2009-02-25 00:34:42.000000', NULL, 1),
(5273357, 767897, 96751, '<td valign="top">Interesting object, but not enough contrast for me.</td>', 'Interesting object, but not enough contrast for me.', '2009-02-25 00:35:12.000000', NULL, 1),
(5273364, 768199, 96751, '<td valign="top">Nice idea.  The cloth looks really silky and textured but the heart looks very flat.  Maybe a different type of paper?</td>', 'Nice idea.  The cloth looks really silky and textured but the heart looks very flat.  Maybe a different type of paper?', '2009-02-25 00:36:48.000000', NULL, 1),
(5273366, 767982, 96751, '<td valign="top">LOL!  What a simple rotation can do.  Very clever.  Great detail on the head.</td>', 'LOL!  What a simple rotation can do.  Very clever.  Great detail on the head.', '2009-02-25 00:37:35.000000', NULL, 1),
(5273369, 768250, 96751, '<td valign="top">Lovely.  The refractions make the left object look like a butterfly.  Great eye.</td>', 'Lovely.  The refractions make the left object look like a butterfly.  Great eye.', '2009-02-25 00:38:09.000000', NULL, 1),
(5273371, 768005, 47294, '<td valign="top">Beautiful concept and execution, very well done. 8</td>', 'Beautiful concept and execution, very well done. 8', '2009-02-25 00:38:27.000000', NULL, 1),
(5273373, 768157, 96751, '<td valign="top">Nice colors and composition!</td>', 'Nice colors and composition!', '2009-02-25 00:39:08.000000', NULL, 1),
(5273380, 767888, 96751, '<td valign="top">I both really love the "rays" but think the "glow" is too overexposed.  I get what you''re trying to do, but the total loss of detail weakens it for me.  If we could still see a tiny bit of the lines (as in the outer areas), it would look more "transparent" and more like light.</td>', 'I both really love the "rays" but think the "glow" is too overexposed.  I get what you''re trying to do, but the total loss of detail weakens it for me.  If we could still see a tiny bit of the lines (as in the outer areas), it would look more "transparent" and more like light.', '2009-02-25 00:40:54.000000', NULL, 1),
(5273397, 767808, 96751, '<td valign="top">Interesting image, nice tones and lighting.</td>', 'Interesting image, nice tones and lighting.', '2009-02-25 00:44:50.000000', NULL, 1),
(5273400, 768120, 63633, '<td valign="top">I haven''t finished voting yet, but I''m sure this is the blue ribbon winner!</td>', 'I haven''t finished voting yet, but I''m sure this is the blue ribbon winner!', '2009-02-25 00:45:57.000000', NULL, 1),
(5273402, 768048, 96751, '<td valign="top">Psychedelic!!!  Very cool colors, textures, and effect.  Wish there were more of a focal point.</td>', 'Psychedelic!!!  Very cool colors, textures, and effect.  Wish there were more of a focal point.', '2009-02-25 00:46:19.000000', NULL, 1),
(5273406, 768002, 96751, '<td valign="top">Very sweet shot.  I think there''s a green tinge to his skin though, similar to the color of the wall.</td>', 'Very sweet shot.  I think there''s a green tinge to his skin though, similar to the color of the wall.', '2009-02-25 00:47:05.000000', NULL, 1),
(5273409, 766655, 96751, '<td valign="top">Interesting collection.  But it''s all about the light for me, and this is a bit flat.</td>', 'Interesting collection.  But it''s all about the light for me, and this is a bit flat.', '2009-02-25 00:47:51.000000', NULL, 1),
(5273410, 767991, 96751, '<td valign="top">Spooky.</td>', 'Spooky.', '2009-02-25 00:48:03.000000', NULL, 1),
(5273411, 768246, 96751, '<td valign="top">Nice!  Great detail on the eyes, although the skin looks over-sharpened.</td>', 'Nice!  Great detail on the eyes, although the skin looks over-sharpened.', '2009-02-25 00:48:43.000000', NULL, 1),
(5273415, 768214, 92546, '<td valign="top">great shot and concept.</td>', 'great shot and concept.', '2009-02-25 00:49:23.000000', NULL, 1),
(5273416, 768003, 96751, '<td valign="top">I''m guessing onion macro.  VERY cool, although it looks a bit unfocused and oversharpened.</td>', 'I''m guessing onion macro.  VERY cool, although it looks a bit unfocused and oversharpened.', '2009-02-25 00:49:38.000000', NULL, 1),
(5273417, 768129, 96751, '<td valign="top">Great cow picture, a bit shoehorned.</td>', 'Great cow picture, a bit shoehorned.', '2009-02-25 00:50:13.000000', NULL, 1),
(5273418, 768200, 96751, '<td valign="top">I love this.  The lighting is very interesting and effective.  I love how it illuminates the interior, the edges of the top front pieces, and the cracks between the pieces in silhouette.  Very clever and well-executed.  Would love to know what that thing is!</td>', 'I love this.  The lighting is very interesting and effective.  I love how it illuminates the interior, the edges of the top front pieces, and the cracks between the pieces in silhouette.  Very clever and well-executed.  Would love to know what that thing is!', '2009-02-25 00:51:19.000000', NULL, 1),
(5273422, 768064, 96751, '<td valign="top">Oh!  This shot helped me see what another one was made of!  I like the idea, but the out of focus area is drawing my eye more than the pretty bloom.</td>', 'Oh!  This shot helped me see what another one was made of!  I like the idea, but the out of focus area is drawing my eye more than the pretty bloom.', '2009-02-25 00:52:22.000000', NULL, 1),
(5273424, 768110, 92546, '<td valign="top">go southwest!</td>', 'go southwest!', '2009-02-25 00:52:39.000000', NULL, 1),
(5273426, 766793, 96751, '<td valign="top">I have no idea what this is but it''s very pretty and colorful.  Love the shapes.</td>', 'I have no idea what this is but it''s very pretty and colorful.  Love the shapes.', '2009-02-25 00:53:07.000000', NULL, 1),
(5273427, 767902, 92546, '<td valign="top">go southwest!</td>', 'go southwest!', '2009-02-25 00:53:28.000000', NULL, 1),
(5273428, 768054, 96751, '<td valign="top">I like the idea.  The image is a bit dull for me.</td>', 'I like the idea.  The image is a bit dull for me.', '2009-02-25 00:53:37.000000', NULL, 1),
(5273429, 766605, 92546, '<td valign="top">go southwest!</td>', 'go southwest!', '2009-02-25 00:53:51.000000', NULL, 1),
(5273430, 768268, 96751, '<td valign="top">Nice mechanical-looking shot.  Love the gray and metallic tones.  Good depth.</td>', 'Nice mechanical-looking shot.  Love the gray and metallic tones.  Good depth.', '2009-02-25 00:54:10.000000', NULL, 1),
(5273431, 767365, 96751, '<td valign="top">Beautiful architectural shot.</td>', 'Beautiful architectural shot.', '2009-02-25 00:54:36.000000', NULL, 1),
(5273437, 768079, 15407, '<td valign="top">The only puzzle for me is were do I find her?</td>', 'The only puzzle for me is were do I find her?', '2009-02-25 00:55:21.000000', NULL, 1),
(5273438, 768155, 96751, '<td valign="top">Nice image but puzzling about "puzzled"...</td>', 'Nice image but puzzling about "puzzled"...', '2009-02-25 00:55:24.000000', NULL, 1),
(5273441, 767982, 92546, '<td valign="top">Aweasome and puzzling!</td>', 'Aweasome and puzzling!', '2009-02-25 00:56:00.000000', NULL, 1),
(5273443, 766771, 96751, '<td valign="top">This is hilarious, if out of focus.  Extra points for head-tilt...</td>', 'This is hilarious, if out of focus.  Extra points for head-tilt...', '2009-02-25 00:56:17.000000', NULL, 1),
(5273444, 768220, 96751, '<td valign="top">Intriguing shapes.</td>', 'Intriguing shapes.', '2009-02-25 00:56:44.000000', NULL, 1),
(5273449, 766795, 96751, '<td valign="top">Very creepy.  Nicely done and very creative.  I''m not wild about the lighting on his face, although the ear and the brain are stellar.  But my taste seems to be in the minority most of the time, so this is certain to finish on the front page :-)</td>', 'Very creepy.  Nicely done and very creative.  I''m not wild about the lighting on his face, although the ear and the brain are stellar.  But my taste seems to be in the minority most of the time, so this is certain to finish on the front page :-)', '2009-02-25 00:58:13.000000', NULL, 1),
(5273455, 767150, 96751, '<td valign="top">Top 10.  Most creative and well-executed.  A slight ding for being slightly washed out on the main face but otherwise, great work.</td>', 'Top 10.  Most creative and well-executed.  A slight ding for being slightly washed out on the main face but otherwise, great work.', '2009-02-25 00:59:12.000000', NULL, 1),
(5273457, 768143, 96751, '<td valign="top">Must be really tough completing a puzzle without seeing the image :-)</td>', 'Must be really tough completing a puzzle without seeing the image :-)', '2009-02-25 00:59:55.000000', NULL, 1),
(5273464, 768079, 96751, '<td valign="top">Holy cow!  Fantastic imagery.  LOVE the matching colors of the sky and foot stool.  LOVE the creamy water and the horizontal dark horizon - which could equally be detracting.  This is going to finish high - at least in my book.</td>', 'Holy cow!  Fantastic imagery.  LOVE the matching colors of the sky and foot stool.  LOVE the creamy water and the horizontal dark horizon - which could equally be detracting.  This is going to finish high - at least in my book.', '2009-02-25 01:01:46.000000', NULL, 1),
(5273466, 767208, 96751, '<td valign="top">Great metallic finish.  Interesting shapes.</td>', 'Great metallic finish.  Interesting shapes.', '2009-02-25 01:02:07.000000', NULL, 1),
(5273470, 768018, 96751, '<td valign="top">The tilt really makes this shot.  Great reflections.</td>', 'The tilt really makes this shot.  Great reflections.', '2009-02-25 01:02:58.000000', NULL, 1),
(5273473, 766585, 96751, '<td valign="top">Not much of a puzzle, but great great perspective shot.  The cone is wonderful but the railing at the foot of the stairs wrecks the otherwise perfect symmetry.</td>', 'Not much of a puzzle, but great great perspective shot.  The cone is wonderful but the railing at the foot of the stairs wrecks the otherwise perfect symmetry.', '2009-02-25 01:04:22.000000', NULL, 1),
(5273476, 768149, 96751, '<td valign="top">Clever, great colors, although the glass of the glasses seems to have lost "transparency".</td>', 'Clever, great colors, although the glass of the glasses seems to have lost "transparency".', '2009-02-25 01:05:05.000000', NULL, 1),
(5273477, 768023, 96751, '<td valign="top">Very cool indeed.  Great work with the negative space.  Might have tried using the same green in the border.</td>', 'Very cool indeed.  Great work with the negative space.  Might have tried using the same green in the border.', '2009-02-25 01:05:47.000000', NULL, 1),
(5273479, 767788, 63633, '<td valign="top">This will ribbon for sure. Fabulously well executed and a striking image.</td>', 'This will ribbon for sure. Fabulously well executed and a striking image.', '2009-02-25 01:06:05.000000', NULL, 1),
(5273480, 768117, 96751, '<td valign="top">Great lines.</td>', 'Great lines.', '2009-02-25 01:06:26.000000', NULL, 1),
(5273481, 767498, 63633, '<td valign="top">This image is stunning. I hope it ribbons for you.</td>', 'This image is stunning. I hope it ribbons for you.', '2009-02-25 01:06:32.000000', NULL, 1),
(5273483, 768194, 96751, '<td valign="top">I love the colors.  I think the texture of the cloth detracts from an otherwise very strong shot.</td>', 'I love the colors.  I think the texture of the cloth detracts from an otherwise very strong shot.', '2009-02-25 01:06:56.000000', NULL, 1),
(5273487, 768255, 96751, '<td valign="top">How very strange.  Love the blue color.</td>', 'How very strange.  Love the blue color.', '2009-02-25 01:07:21.000000', NULL, 1),
(5273491, 768154, 96751, '<td valign="top">Oh man, what an incredible amount of work.  Most intense execution.  Top 10, even though I think the thumb area could have used a TINY bit more light, just to define the edges.  Great job.</td>', 'Oh man, what an incredible amount of work.  Most intense execution.  Top 10, even though I think the thumb area could have used a TINY bit more light, just to define the edges.  Great job.', '2009-02-25 01:08:38.000000', NULL, 1),
(5273494, 768225, 96751, '<td valign="top">Beautiful colors, very modern art-like.</td>', 'Beautiful colors, very modern art-like.', '2009-02-25 01:09:04.000000', NULL, 1),
(5273497, 767350, 96751, '<td valign="top">SO cute.  There is so much you can say with just an eye and a snoot...</td>', 'SO cute.  There is so much you can say with just an eye and a snoot...', '2009-02-25 01:09:48.000000', NULL, 1),
(5273500, 768114, 96751, '<td valign="top">I guess they do make a puzzle!  Beautiful shot.  Love the selective desat.  Very strong diagonal.  Good eye.</td>', 'I guess they do make a puzzle!  Beautiful shot.  Love the selective desat.  Very strong diagonal.  Good eye.', '2009-02-25 01:10:54.000000', NULL, 1),
(5273501, 767530, 96751, '<td valign="top">I like the idea but not the lighting.</td>', 'I like the idea but not the lighting.', '2009-02-25 01:11:18.000000', NULL, 1),
(5273504, 768005, 96751, '<td valign="top">That is one heck of a reflection.  Just gorgeous.  This should finish very well.  I love how unexpected the colors are in the otherwise dreary surrounding.  Surreal and wonderful.</td>', 'That is one heck of a reflection.  Just gorgeous.  This should finish very well.  I love how unexpected the colors are in the otherwise dreary surrounding.  Surreal and wonderful.', '2009-02-25 01:12:28.000000', NULL, 1),
(5273509, 767915, 96751, '<td valign="top">Interesting use of a banana.  If only the same amount of time had been spent on the lighting...</td>', 'Interesting use of a banana.  If only the same amount of time had been spent on the lighting...', '2009-02-25 01:13:10.000000', NULL, 1),
(5273511, 768242, 96751, '<td valign="top">Hilarious!  Incredible colors.</td>', 'Hilarious!  Incredible colors.', '2009-02-25 01:13:54.000000', NULL, 1),
(5273512, 767371, 96751, '<td valign="top">This bug is really making the rounds.  Absolutely incredible capture.  Love the crossed twigs as counterpoint to the explosion of droplets, and the star flare. I''m faving it, but is this REALLY a Puzzled shot?  Will likely ribbon as I am always wrong about these things...</td>', 'This bug is really making the rounds.  Absolutely incredible capture.  Love the crossed twigs as counterpoint to the explosion of droplets, and the star flare. I''m faving it, but is this REALLY a Puzzled shot?  Will likely ribbon as I am always wrong about these things...', '2009-02-25 01:15:28.000000', NULL, 1),
(5273513, 767798, 96751, '<td valign="top">Very cool macro.  Made me stop to try and figure it out.</td>', 'Very cool macro.  Made me stop to try and figure it out.', '2009-02-25 01:16:01.000000', NULL, 1),
(5273515, 768146, 96751, '<td valign="top">Sort of "through the looking glass"</td>', 'Sort of "through the looking glass"', '2009-02-25 01:16:27.000000', NULL, 1),
(5273516, 768198, 96751, '<td valign="top">Clever.  Great expression.  Incredible eyes.</td>', 'Clever.  Great expression.  Incredible eyes.', '2009-02-25 01:16:56.000000', NULL, 1),
(5273519, 768261, 96751, '<td valign="top">The colors are just gorgeous on this.  The overall picture doesn''t make much sense to me.  I don''t understand the relationship between the basket, the torn paper and the cube.  The cube alone would have been stellar.</td>', 'The colors are just gorgeous on this.  The overall picture doesn''t make much sense to me.  I don''t understand the relationship between the basket, the torn paper and the cube.  The cube alone would have been stellar.', '2009-02-25 01:17:56.000000', NULL, 1),
(5273521, 766700, 15407, '<td valign="top">Why the crop in the left most roof top? Something UGLY?  Lost a point to that...</td>', 'Why the crop in the left most roof top? Something UGLY?  Lost a point to that...', '2009-02-25 01:18:34.000000', NULL, 1),
(5273523, 768179, 96751, '<td valign="top">Fun shot.</td>', 'Fun shot.', '2009-02-25 01:18:38.000000', NULL, 1),
(5273524, 766978, 96751, '<td valign="top">Nice mood lighting.  The coffee looks a tad inky though.</td>', 'Nice mood lighting.  The coffee looks a tad inky though.', '2009-02-25 01:19:03.000000', NULL, 1),
(5273526, 768134, 96751, '<td valign="top">Great abstract.</td>', 'Great abstract.', '2009-02-25 01:19:19.000000', NULL, 1),
(5273527, 768059, 9602, '<td valign="top">Noise level on this is really bad, may have been partially saved by replacing the background.</td>', 'Noise level on this is really bad, may have been partially saved by replacing the background.', '2009-02-25 01:19:39.000000', NULL, 1),
(5273528, 767747, 96751, '<td valign="top">Another ice floe shot.  This one is a bit flat, light-wise</td>', 'Another ice floe shot.  This one is a bit flat, light-wise', '2009-02-25 01:19:39.000000', NULL, 1),
(5273529, 768042, 96751, '<td valign="top">Great lighting!!!!  Love the shadows.  Really enhances the puzzle.</td>', 'Great lighting!!!!  Love the shadows.  Really enhances the puzzle.', '2009-02-25 01:20:04.000000', NULL, 1),
(5273530, 767966, 96751, '<td valign="top">Nice dof and selective desat.  Colors are a bit dull though.</td>', 'Nice dof and selective desat.  Colors are a bit dull though.', '2009-02-25 01:20:47.000000', NULL, 1),
(5273531, 767991, 9602, '<td valign="top">Nice idea; though I think I may have made the piece gaps smaller, and taken a few edge pieces and moved them so they didn''t fit perfectly.</td>', 'Nice idea; though I think I may have made the piece gaps smaller, and taken a few edge pieces and moved them so they didn''t fit perfectly.', '2009-02-25 01:21:15.000000', NULL, 1),
(5273533, 768078, 96751, '<td valign="top">A fun and colorful shot.</td>', 'A fun and colorful shot.', '2009-02-25 01:21:36.000000', NULL, 1),
(5273535, 767083, 9602, '<td valign="top">Nice idea, but I would have used a textured background for the white space to make it a little less harsh to look at.</td>', 'Nice idea, but I would have used a textured background for the white space to make it a little less harsh to look at.', '2009-02-25 01:22:03.000000', NULL, 1),
(5273536, 767821, 96751, '<td valign="top">Complex idea.  Overall, the image is a bit flat.</td>', 'Complex idea.  Overall, the image is a bit flat.', '2009-02-25 01:22:07.000000', NULL, 1),
(5273537, 766832, 9602, '<td valign="top">Should have gone with fractures title.</td>', 'Should have gone with fractures title.', '2009-02-25 01:22:34.000000', NULL, 1),
(5273541, 768267, 9602, '<td valign="top">I like the picture, but think you could have gone with a better title; but I''m not holding that against you.</td>', 'I like the picture, but think you could have gone with a better title; but I''m not holding that against you.', '2009-02-25 01:23:26.000000', NULL, 1),
(5273544, 767949, 9602, '<td valign="top">Great colors in this; and DOF.</td>', 'Great colors in this; and DOF.', '2009-02-25 01:24:11.000000', NULL, 1),
(5273546, 766754, 96751, '<td valign="top">A top finisher for sure.  Wonderful use of selective desat.  Very cool cutout, interesting composition, love the frame tilt with the head.  To be really picky, the lamp or plant or whatever in the upper left corner is distracting, as is the area between the thumb and t-shirt on the right.  All this work on the subject, and a distracting background. Tsk tsk.  Still, love it.</td>', 'A top finisher for sure.  Wonderful use of selective desat.  Very cool cutout, interesting composition, love the frame tilt with the head.  To be really picky, the lamp or plant or whatever in the upper left corner is distracting, as is the area between the thumb and t-shirt on the right.  All this work on the subject, and a distracting background. Tsk tsk.  Still, love it.', '2009-02-25 01:25:04.000000', NULL, 1),
(5273549, 768119, 96751, '<td valign="top">Interesting silhouette.</td>', 'Interesting silhouette.', '2009-02-25 01:25:23.000000', NULL, 1),
