(5273553, 768186, 96751, '<td valign="top">Very funny.  Nice execution.  Don''t know that I like the combination of color AND b/w on the puzzle.</td>', 'Very funny.  Nice execution.  Don''t know that I like the combination of color AND b/w on the puzzle.', '2009-02-25 01:26:19.000000', NULL, 1),
(5273568, 767915, 15407, '<td valign="top">Towards the light or the crack!</td>', 'Towards the light or the crack!', '2009-02-25 01:35:25.000000', NULL, 1),
