(5274512, 767202, 18655, '<td valign="top">Puzzling indeed and an overall nice shot.</td>', 'Puzzling indeed and an overall nice shot.', '2009-02-25 13:49:14.000000', NULL, 1),
(5274514, 768193, 18655, '<td valign="top">Always dangerous! Sharp and creative.</td>', 'Always dangerous! Sharp and creative.', '2009-02-25 13:50:01.000000', NULL, 1),
(5274517, 767371, 101668, '<td valign="top">This deserves a ten. It is a most spectacular picture but now I am puzzled. Puzzled? Well in case I simply dont see it, I am scoring it a 10!!</td>', 'This deserves a ten. It is a most spectacular picture but now I am puzzled. Puzzled? Well in case I simply dont see it, I am scoring it a 10!!', '2009-02-25 13:52:29.000000', NULL, 1),
(5274526, 768119, 18655, '<td valign="top">I have to think about this one for a bit... let''s see: thought provoking, definitely a puzzle. Is it a shade? Or what is it? To me this is very illustrative of all the questions a person is facing throughout his/hers life. I could easily see this in a photo exhibition. If a known photographer/artist had done it, I''m sure it would have cost an  arm and a leg.<br/>Probably not appreciated by the DPC masses but appreciated by me. The hand drawn (at least it looks that way) pieces tops it. The background adding to the illustration that we really know nothing in the big scheme is very suitable.<br/> <br/>I could easily have this on my wall in my study!<br/> <br/>Not sure how you came up with this but for me this is a clear 10.</td>', 'I have to think about this one for a bit... let''s see: thought provoking, definitely a puzzle. Is it a shade? Or what is it? To me this is very illustrative of all the questions a person is facing throughout his/hers life. I could easily see this in a photo exhibition. If a known photographer/artist had done it, I''m sure it would have cost an  arm and a leg.Probably not appreciated by the DPC masses but appreciated by me. The hand drawn (at least it looks that way) pieces tops it. The background adding to the illustration that we really know nothing in the big scheme is very suitable. I could easily have this on my wall in my study! Not sure how you came up with this but for me this is a clear 10.', '2009-02-25 14:00:26.000000', NULL, 1),
(5274529, 767798, 18655, '<td valign="top">Indeed!! Overall a great image. I like it a lot!</td>', 'Indeed!! Overall a great image. I like it a lot!', '2009-02-25 14:01:27.000000', NULL, 1),
