(5276140, 767664, 6999, '<td valign="top">This is groovy; I kind of like the refusal to deal with anything approaching the bright lights here. Much of this challenge features the bleedin'' obvious, and this has far greater depth and sincerity.</td>', 'This is groovy; I kind of like the refusal to deal with anything approaching the bright lights here. Much of this challenge features the bleedin'' obvious, and this has far greater depth and sincerity.', '2009-02-26 13:17:30.000000', NULL, 1),
(5276143, 766585, 6999, '<td valign="top">More arresting than most - and, on a meta-reactive level, leaves me slightly puzzled as to what I think; although at least it asks me to think at all, which is a pleasant change.</td>', 'More arresting than most - and, on a meta-reactive level, leaves me slightly puzzled as to what I think; although at least it asks me to think at all, which is a pleasant change.', '2009-02-26 13:19:56.000000', NULL, 1),
