(5281327, 767788, 101730, '<td valign="top">I vote this one is blue ribbon and I''m pretty sure a biological impossiblity (after I spent the afternoon scouring my local garden center looking for an orchid with chocolates growing from a tomato stem). Very well executed.</td>', 'I vote this one is blue ribbon and I''m pretty sure a biological impossiblity (after I spent the afternoon scouring my local garden center looking for an orchid with chocolates growing from a tomato stem). Very well executed.', '2009-03-01 15:23:29.000000', NULL, 1),
(5281331, 767888, 101730, '<td valign="top">Haha, I''ve grown a little tired of all the puzzle pieces in this challenge, but this is a cool way to depict that almost magical moment when you finish that 10000 piece puzzle. Well executed, too.</td>', 'Haha, I''ve grown a little tired of all the puzzle pieces in this challenge, but this is a cool way to depict that almost magical moment when you finish that 10000 piece puzzle. Well executed, too.', '2009-03-01 15:26:54.000000', NULL, 1),
