(5289054, 768114, 82985, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=677021" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg"/></a>PostLuminous Award Nominee!<br/>well seen, well composed, well executed, and stands on its own apart from any challenge theme.  well done!</td>', 'PostLuminous Award Nominee!well seen, well composed, well executed, and stands on its own apart from any challenge theme.  well done!', '2009-03-04 15:41:28.000000', NULL, 0),
(5289058, 767498, 82985, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=677021" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg"/></a>PostLuminous Award Nominee!<br/>This is fantastic, and that assessment is before I apply my personal love-of-agave multiplier :-)</td>', 'PostLuminous Award Nominee!This is fantastic, and that assessment is before I apply my personal love-of-agave multiplier :-)', '2009-03-04 15:42:54.000000', NULL, 0),
(5289059, 766655, 82985, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=677021" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg"/></a>PostLuminous Award Nominee!<br/>nicely seen, beautiful soft, unsaturated color tones, textures</td>', 'PostLuminous Award Nominee!nicely seen, beautiful soft, unsaturated color tones, textures', '2009-03-04 15:44:34.000000', NULL, 0),
(5289078, 768120, 71664, '<td valign="top">Congrats! Really interesting and great photo.</td>', 'Congrats! Really interesting and great photo.', '2009-03-04 15:51:34.000000', NULL, 0),
(5289084, 768086, 82985, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=677020" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677020.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677020.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677020.jpg"/></a>PostLuminous Award WINNER!<br/> <br/>WOW.<br/> <br/>I say again:  WOW.<br/> <br/>This is a remarkable scene, a fascinating image to ponder, and superbly seen &amp; executed.<br/> <br/>WOW.</td>', 'PostLuminous Award WINNER! WOW. I say again:  WOW. This is a remarkable scene, a fascinating image to ponder, and superbly seen & executed. WOW.', '2009-03-04 15:54:10.000000', NULL, 0),
(5289086, 767218, 30364, '<td valign="top">I''ve just realized that it''s <i>not</i> a b-ball.  It''s a balloon.  I thought he was taking a free shot.  I give him the point anyway.</td>', 'I''ve just realized that it''s not a b-ball.  It''s a balloon.  I thought he was taking a free shot.  I give him the point anyway.', '2009-03-04 15:55:08.000000', NULL, 0),
(5289190, 767218, 35545, '<td valign="top">Street photography in the best sense of the word, and a puzzler to boot.  This shot has it all: people doing their own thing, abandoned store front, pay phone, ATM...  What are they up to????<br/> <br/>I don''t vote challenges much anymore, but I''d have voted this highly.  Great shot.</td>', 'Street photography in the best sense of the word, and a puzzler to boot.  This shot has it all: people doing their own thing, abandoned store front, pay phone, ATM...  What are they up to???? I don''t vote challenges much anymore, but I''d have voted this highly.  Great shot.', '2009-03-04 16:35:22.000000', NULL, 0),
